export function freshBudget(){return {seen:[],diagnosis:null,choice:null,brief:false};}
export function restoreBudget(v){const s=freshBudget();if(!v||typeof v!=='object')return s;s.seen=[...new Set((Array.isArray(v.seen)?v.seen:[]).filter(id=>documents.some(d=>d.id===id)))];s.diagnosis=['uncertain','all-clear','loan'].includes(v.diagnosis)?v.diagnosis:null;s.choice=scenarios.some(c=>c.id===v.choice)?v.choice:null;s.brief=v.brief===true&&s.seen.length===4&&s.diagnosis==='uncertain'&&!!s.choice;return s;}
export function assess(s){if(s.seen.length!==4)return {ok:false,reason:'Consulter les quatre pièces avant de préparer le diagnostic.'};if(s.diagnosis!=='uncertain')return {ok:false,reason:'Le financement annoncé n’est pas acquis et les charges de fonctionnement doivent être prises en compte.'};return {ok:true,reason:'Diagnostic prudent : la recette annoncée reste incertaine. Les scénarios sont des hypothèses, pas une autorisation de dépense.'};}
export function evaluate(s){const pre=assess(s);if(!pre.ok||!s.choice)return {...pre,ok:false};const c=scenarios.find(x=>x.id===s.choice);return {ok:true,scenario:c,investmentNeed:c.investment-c.grant,municipalEnvelope:1850000,gap:c.investment-c.grant-1850000,annual:c.annual};}
